41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	
47	const BASE_PREMIUMS: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	
56	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
57	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
58	
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_PREMIUM = 60;
61	
62	const countsByType = (items: Item[]): Map<string, number> =>
63	  items.reduce(
64	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
65	    new Map<string, number>(),
66	  );
67	
68	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
69	
70	/** Exactly three alike components form a building block, priced at a flat rate. */
71	const basePremiumForAlikeItems = (type: string, count: number): number =>
72	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
73	    ? COMPONENT_BLOCK_PREMIUM
74	    : count * BASE_PREMIUMS[type];
75	
76	const policyBasePremium = (items: Item[]): number =>
77	  [...countsByType(items)].reduce(
78	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
79	    0,
80	  );
81	
82	/** Modifiers are rates on a base premium, not on each other. Returns the surcharge alone. */
83	const rateOf = (basePremium: number, rate: number): number => basePremium * rate;
84	
85	/** Item-specific surcharge rates stack additively on the item's own base premium. */
86	const surchargeRateFor = (item: Item): number =>
87	  (item.cursed ? CURSE_SURCHARGE : 0) +
88	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0);
89	
90	/** Item-specific surcharges are rates on the affected item's own base premium. */
91	const itemSurcharges = (items: Item[]): number =>
92	  items.reduce(
93	    (total, item) => total + rateOf(BASE_PREMIUMS[item.type], surchargeRateFor(item)),
94	    0,
95	  );
96	
97	const quote = (step: QuoteStep): StepResult => {
98	  const base = policyBasePremium(step.items);
99	  return {
100	    premium: roundPremiumInMHPCOFavour(
101	      base +
102	        itemSurcharges(step.items) +
103	        rateOf(base, INITIAL_ASSESSMENT_SURCHARGE) +
104	        PROCESSING_FEE,
105	    ),
106	  };
107	};
108	
109	const runStep = (step: Step): StepResult => {
110	  if (step.op === "quote") return quote(step);
111	  throw new Error(`Unsupported step: ${step.op}`);
112	};
113	
114	export const runScenario = (scenario: Scenario): ScenarioResult => ({
115	  results: scenario.steps.map(runStep),
116	});
